"""A tiny calculator module used as a PartB smoke-test target."""


class DivisionError(Exception):
    """Raised when dividing by zero."""


class Calculator:
    """A small stateful calculator with a running total."""

    def __init__(self, initial: float = 0.0) -> None:
        self.total = initial

    def add(self, value: float) -> float:
        """Add ``value`` to the running total and return the new total."""
        self.total += value
        return self.total

    def subtract(self, value: float) -> float:
        """Subtract ``value`` from the running total and return the new total."""
        self.total -= value
        return self.total

    def multiply(self, value: float) -> float:
        """Multiply the running total by ``value`` and return the new total."""
        self.total *= value
        return self.total

    def divide(self, value: float) -> float:
        """Divide the running total by ``value`` and return the new total.

        Raises:
            DivisionError: if ``value`` is zero.
        """
        if value == 0:
            raise DivisionError("cannot divide by zero")
        self.total /= value
        return self.total

    def reset(self) -> float:
        """Reset the running total to zero and return it."""
        self.total = 0.0
        return self.total


def clamp(value: float, low: float, high: float) -> float:
    """Clamp ``value`` to the inclusive range [low, high]."""
    if low > high:
        raise ValueError("low must be <= high")
    if value < low:
        return low
    if value > high:
        return high
    return value


def is_even(n: int) -> bool:
    """Return True if ``n`` is even."""
    return n % 2 == 0

